mapper.select:
select
,



    a.deleted = 0


            and (a.title like concat('%', #{q.keyword}, '%')
            or a.summary like concat('%', #{q.keyword}, '%')
            or a.content like concat('%', #{q.keyword}, '%'))


            and a.category_id = #{q.categoryId}


            and a.status = #{q.status}


            and a.visibility = #{q.visibility}


            and a.priority = #{q.priority}


            and a.campus = #{q.campus}


            and a.dept_id = #{q.deptId}


            and a.author_id = #{q.authorId}


            and a.is_top = 1


            and a.create_time >= #{q.startTime}


            and a.create_time <= #{q.endTime}



order by a.is_top desc, a.priority desc, a.publish_time desc, a.id desc

select ,
where a.deleted = 0 and a.status = 'PUBLISHED' order by a.view_count desc, a.id desc
limit #{limit}
